// Dreaminator — multi-language UI translations & browser language detection.
// Plain ES module (no build step): embedded directly into the receiver binary.

export const LANGUAGES = [
  { code: 'en', label: 'English' },
  { code: 'fr', label: 'Français' },
  { code: 'pt', label: 'Português' },
  { code: 'es', label: 'Español' },
  { code: 'it', label: 'Italiano' },
  { code: 'de', label: 'Deutsch' },
  { code: 'pl', label: 'Polski' },
  { code: 'cs', label: 'Čeština' },
  { code: 'tr', label: 'Türkçe' },
  { code: 'he', label: 'עברית' },
  { code: 'ar', label: 'العربية' },
  { code: 'ja', label: '日本語' },
  { code: 'zh', label: '中文' },
  { code: 'th', label: 'ไทย' },
  { code: 'ru', label: 'Русский' },
];

export const LOCALE_MAP = {
  pt: 'pt-PT',
  fr: 'fr-FR',
  he: 'he-IL',
  ar: 'ar-SA',
  it: 'it-IT',
  de: 'de-DE',
  es: 'es-ES',
  pl: 'pl-PL',
  en: 'en-US',
  ja: 'ja-JP',
  zh: 'zh-CN',
  th: 'th-TH',
  tr: 'tr-TR',
  cs: 'cs-CZ',
  ru: 'ru-RU',
};

const SUPPORTED = new Set(LANGUAGES.map((l) => l.code));

export function isRTL(lang) {
  return lang === 'he' || lang === 'ar';
}

export function normalizeLang(tag) {
  if (!tag || typeof tag !== 'string') return '';
  let s = tag.trim().toLowerCase().replace(/_/g, '-');
  if (!s || s === 'auto') return '';
  const primary = s.split('-')[0];
  if (primary === 'iw') return 'he';
  if (primary === 'cz') return 'cs';
  if (primary === 'jp') return 'ja';
  return SUPPORTED.has(primary) ? primary : '';
}

export function detectBrowserLanguage() {
  if (typeof navigator === 'undefined') return '';
  const list = Array.isArray(navigator.languages) && navigator.languages.length
    ? navigator.languages
    : (navigator.language ? [navigator.language] : []);
  for (const tag of list) {
    const code = normalizeLang(tag);
    if (code) return code;
  }
  return '';
}

const memStore = {
  get(k) { try { return typeof localStorage !== 'undefined' ? localStorage.getItem(k) : null; } catch { return null; } },
  set(k, v) { try { if (typeof localStorage !== 'undefined') localStorage.setItem(k, v); } catch { /* private mode */ } },
};

export function getLanguagePref() {
  const pref = memStore.get('lang');
  if (!pref || pref === 'auto') return 'auto';
  return normalizeLang(pref) || 'auto';
}

export function setLanguagePref(pref) {
  if (!pref || pref === 'auto') {
    memStore.set('lang', 'auto');
    return 'auto';
  }
  const norm = normalizeLang(pref) || 'auto';
  memStore.set('lang', norm);
  return norm;
}

export function getLanguage(serverLang = '') {
  const pref = getLanguagePref();
  if (pref !== 'auto') return pref;
  return detectBrowserLanguage() || normalizeLang(serverLang) || 'ru';
}

