export function trServer(text, lang = getLanguage()) {
  if (!text || lang === 'ru') return text;
  const entry = SERVER_MAP[text];
  if (entry && entry[lang]) return entry[lang];
  return text;
}

export function t(key, vars = null, lang = getLanguage()) {
  const dict = STRINGS[lang] || STRINGS.ru;
  let str = dict[key];
  if (str === undefined) str = STRINGS.ru[key] ?? key;
  if (vars) {
    for (const [k, v] of Object.entries(vars)) {
      str = str.replaceAll(`{${k}}`, String(v));
    }
  }
  return str;
}

export function pluralForm(n, lang = getLanguage()) {
  const m10 = n % 10;
  const m100 = n % 100;
  if (lang === 'ru') {
    if (m10 === 1 && m100 !== 11) return 'one';
    if (m10 >= 2 && m10 <= 4 && (m100 < 12 || m100 > 14)) return 'few';
    return 'many';
  }
  if (lang === 'pl') {
    if (n === 1) return 'one';
    if (m10 >= 2 && m10 <= 4 && (m100 < 12 || m100 > 14)) return 'few';
    return 'many';
  }
  if (lang === 'cs') {
    if (n === 1) return 'one';
    if (n >= 2 && n <= 4) return 'few';
    return 'many';
  }
  if (lang === 'ja' || lang === 'zh' || lang === 'th') return 'many';
  if (lang === 'fr') return n <= 1 ? 'one' : 'many';
  return n === 1 ? 'one' : 'many';
}

export const channelsWord = (n, lang = getLanguage()) => t(`ch_${pluralForm(n, lang)}`, { n }, lang);
export const entriesWord = (n, lang = getLanguage()) => t(`ent_${pluralForm(n, lang)}`, { n }, lang);
export const sourcesWord = (n, lang = getLanguage()) => t(`src_${pluralForm(n, lang)}`, { n }, lang);
export const daysWord = (n, lang = getLanguage()) => t(`day_${pluralForm(n, lang)}`, { n }, lang);
export const noLogoWord = (n, lang = getLanguage()) => t(`nologo_${pluralForm(n, lang)}`, { n }, lang);

export function localeOf(lang = getLanguage()) {
  return LOCALE_MAP[lang] || 'en-US';
}

export function when(iso, lang = getLanguage()) {
  if (!iso) return '';
  const d = new Date(iso);
  const diff = (Date.now() - d) / 60000;
  if (diff < 1) return t('time_just_now', null, lang);
  if (diff < 60) return t('time_min_ago', { n: Math.round(diff) }, lang);
  const loc = localeOf(lang);
  const time = d.toLocaleTimeString(loc, { hour: '2-digit', minute: '2-digit' });
  const today = new Date();
  const yesterday = new Date(Date.now() - 86400000);
  if (d.toDateString() === today.toDateString()) return t('time_today_at', { time }, lang);
  if (d.toDateString() === yesterday.toDateString()) return t('time_yesterday_at', { time }, lang);
  const date = d.toLocaleDateString(loc, { day: 'numeric', month: 'long' });
  return t('time_date_at', { date, time }, lang);
}

export function fmtDate(iso, lang = getLanguage()) {
  return new Date(iso).toLocaleDateString(localeOf(lang), { day: 'numeric', month: 'long', year: 'numeric' });
}

export function applyDocumentLanguage(lang = getLanguage()) {
  if (typeof document === 'undefined') return;
  const el = document.documentElement;
  el.lang = lang;
  el.dir = isRTL(lang) ? 'rtl' : 'ltr';
  const tabMap = {
    channels: 'nav_channels',
    lists: 'nav_lists',
    sources: 'nav_sources',
    settings: 'nav_settings',
  };
  for (const a of document.querySelectorAll('.nav a')) {
    const key = tabMap[a.dataset.tab];
    if (!key) continue;
    const label = a.querySelector('.nav-label');
    if (label) label.textContent = t(key, null, lang);
    else {
      // Preserve leading icon if present
      const svg = a.querySelector('svg');
      a.textContent = t(key, null, lang);
      if (svg) a.prepend(svg);
    }
  }
}
